-- ============================================================================
-- عنقود المغادرة إلى سوريا: 18 صفحة ← 9 (2026-08-06)
-- ============================================================================
-- أخطر عنقود على الموقع. الجواب الخاطئ هنا لا يكلّف القارئ رحلة ضائعة — يكلّفه
-- حمايته المؤقتة، نهائياً.
--
-- ── 1) صفحتان تُلصقان الكود الخطأ بالنتيجة ────────────────────────────────
--
-- وجدول الأكواد المدقَّق عندنا هو ما يُثبت ذلك: 125 كوداً روجعت على مصادر
-- معتمدة في تدقيق سابق، وهي تقول:
--     V-87  = عودة طوعية        (إداري)
--     G-87  = تهديد الأمن العام  (أمن وجرائم)
--     V-160 = تجميد عنوان        (حتى العثور على الشخص أو تثبيت عنوانه)
--
-- صفحة «زيارة سوريا بالكملك» تقول للقارئ إنّ العبور غير الرسمي يضع كود G-87 —
-- وهو كود أمني أثقل بكثير ممّا تصفه. وصفحة «أذونات السفر 2026» تقول إنّ السفر
-- بلا إذن يُبطل الكملك بالكود V-160 — وV-160 تجميد عنوان لا إبطال بطاقة.
-- الادّعاءان لا يبقيان، ولا يُنقلان إلى الصفحة الباقية: هذا الملف لا ينقل
-- تسمية كود لا يطابق الجدول المدقَّق.
--
-- ── 2) صفحة تمرّ بوسيط ───────────────────────────────────────────────────
--
-- «اجازات ل سوريا 2026» متنها إحدى عشرة كلمة، وخطواتها الأربع: قدّم طلباً
-- لتصير عضواً في «المنظمة»، واطلب منهم رفع طلبك، وانتظر عشرة إلى عشرين يوماً،
-- ثم اذهب إلى المعبر بـ«الموافقة الشفهية». وهذا بعينه ما تحذّر منه كل صفحة
-- أخرى في العنقود، وما يمنعه CLAUDE.md صراحةً. تُحذف ولا يُنقل منها حرف —
-- الصفحة الوحيدة التي عوملت هكذا في عشر تمريرات.
--
-- ── 3) والباقي الشكل المعتاد ─────────────────────────────────────────────
--
-- عمود العودة الطوعية (1,397 كلمة) تدور حوله خمس صفحات بين 30 و175 كلمة تعيد
-- صياغته، وصفحة إذن السفر ومعها اثنتان.
--
-- وما تكسبه الصفحة الباقية بدل تسميات الأكواد: النتيجة مقولةً صراحةً — المغادرة
-- بلا إذن مسبق قد تُنهي الحماية — ورابط صفحة الأكواد ليبحث القارئ عن معنى أي
-- كود يراه فعلاً، بدل أن يُقال له سلفاً أيّ كود سيناله.
--
-- شغّله بعد اكتمال نشر الشيفرة (التحويلات في next.config.ts).
-- ============================================================================

-- travel-permit  ←  1 صفحة
UPDATE articles SET
    documents = ARRAY['شيفرة e-Devlet.', 'بطاقة الحماية المؤقتة (كملك).', 'وثيقة سبب السفر (حسب الحالة): إذن عمل/SGK، إحالة أو تقرير طبي (Sevk)، موعد قنصلية، دعوة/موعد معرض أو فعالية، وثيقة وفاة، أو وثائق لمّ شمل/دفتر عائلة تركي (عند الانطباق).', 'إذا كنت ستسافر بسيارتك: رقم اللوحة (Araç Plaka).', 'تقرير طبي أو إحالة من مشفى حكومي', 'صورة الكملك']::text[],
    steps = ARRAY['سجّل دخولك إلى e-Devlet وابحث عن: “Yabancılar İçin Yol İzin Belge Başvurusu”.', 'اضغط “Yeni Başvuru” لإنشاء طلب جديد.', 'قبل تعبئة الطلب: قيّم الولاية المقصودة إن كانت “مفتوحة” أو من الولايات المحظورة/الحساسة (القوائم قد تتغير).', 'اختر سبب السفر في خانة “Talep Nedeni”. للولايات المفتوحة: غالباً خيار “زيارة (Ziyaret)” هو المسار المعتاد. للولايات الحساسة: اختر السبب الأقوى الذي ينطبق عليك (عمل/صحة/لم شمل/تعليم/غيره) وأرفق وثائقه الرسمية.', 'حدد الولاية المراد زيارتها والفترة/التاريخ.', 'أدخل رقم لوحة السيارة إذا كان السفر بسيارة خاصة.', 'أرفق وثيقة داعمة في خانة “Ek Belgeler”، ثم أرسل الطلب وتابع النتيجة.', 'احصل على إحالة طبية (Sevk) من مشفى حكومي في ولايتك', 'ادخل بوابة e-Devlet وابحث عن (Yol İzin Belgesi)', 'أرفق الإحالة الطبية مع الطلب', 'انتظر الموافقة (سريعة للحالات الطارئة)', 'اختر سبب الطلب: زيارة (Ziyaret)', 'حدد الولاية المراد السفر إليها وتاريخ الذهاب والعودة', 'أدخل معلومات المضيف (اسمه ورقم TC الخاص به)', 'انتظر الرد (قد يستغرق 1-5 أيام)', 'المرفقات: أرفق وثيقة تثبت السبب (دعو، تقرير طبي، وثيقة طالب...).']::text[],
    tips = ARRAY['للولايات المفتوحة: اطلب مدة منطقية وسبباً واضحاً (زيارة) مع ملف مرتب وواضح.', 'للولايات الحساسة: “زيارة” لوحدها قد لا تكفي؛ جهّز مبرراً قوياً ووثيقة رسمية واضحة.', 'قد تصل نتيجة الطلب عبر SMS أو تظهر ضمن الطلبات في e-Devlet.', 'قد تختلف الشروط حسب الولاية والمرحلة الزمنية، لذلك احتفظ بصورة من الطلب والوثائق المرفقة ولا تعتمد على تجارب قديمة.', 'تأكد أن التقرير الطبي واضح ومختوم لتسريع الموافقة', 'في حالات الإسعاف الطارئ جداً يُسمح بالسفر بدون إذن مسبق', 'الإذن مجاني تماماً', 'قدّم الطلب قبل موعد سفرك بـ 3 أيام على الأقل', 'يمكن للمسؤولين رفض الإذن دون ذكر أسباب', 'إذا كنت بحاجة لعلاج غير متوفر في ولايتك، يمكنك طلب إذن سفر طبي عبر e-Devlet.', 'يمكنك طلب إذن سفر لزيارة عائلية أو أغراض شخصية عبر بوابة e-Devlet.', 'طلبات السفر للولايات المحظورة (مثل إسطنبول وأنقرة) تُرفض غالباً.', 'إذن السفر ضروري لقطع تذاكر الباص والطائرة.']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'travel-permit';

-- syria-turkey-border-crossings-2026  ←  2 صفحة
UPDATE articles SET
    documents = ARRAY['بطاقة الإقامة التركية (ikamet) سارية — أو إذن عمل مستقل عن الحماية المؤقتة', 'جواز سفر سوري ساري', 'إثبات سوري (هوية أو إخراج قيد) عند الحاجة', 'لحاملي إقامة دولة ثالثة: وثيقة الإقامة أو جواز الجنسية الثالثة']::text[],
    steps = ARRAY['حدّد وضعك القانوني بدقّة: إقامة، أم إذن عمل مستقل، أم حماية مؤقتة (كملك).', 'إن كنت تحمل الكملك: أنت غير مشمول بقرار 1 كانون الثاني 2026 — راجع إدارة الهجرة قبل أي تخطيط.', 'تأكّد أن وثائقك سارية وليست قيد التجديد.', 'اختر معبراً من الستة المشمولة، واتصل به في اليوم السابق للسفر.', 'إن كنت من حاملي إقامة دولة ثالثة: خطّط للعودة من المعبر نفسه الذي دخلت منه.', 'اخرج وعُد عبر المعبر الرسمي المحدد فقط']::text[],
    tips = ARRAY['الفرق بين «الإقامة» و«الكملك» هو الفارق الحاسم — لا تخلط بينهما.', 'الإقامة المقبولة: سياحية أو مستثمر أو عمل. إذن العمل على الكملك لا يكفي.', 'المعابر المشمولة ستة: كسب، باب الهوى، الحمام، باب السلامة، الراعي، جرابلس.', 'الإشاعات تكثر قبل الأعياد: «تأكد» كذّبت في أيار 2026 ادعاء سماح العبور لحملة الكملك.', 'اتصل بالمعبر قبل السفر بيوم — لا تعتمد على منشور متداوَل.', 'لا تدفع لوسيط مقابل «تسهيل العبور».', 'هذا البرنامج موسمي وقد يتوقف — تأكد من توفره قبل التخطيط', 'تجنّب السماسرة الذين يدّعون ترتيب إجازات مدفوعة']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'syria-turkey-border-crossings-2026';

-- voluntary-return-syria-procedure-2026  ←  5 صفحة
UPDATE articles SET
    documents = ARRAY['بطاقة الكملك الأصلية (إلزامي)', 'إثبات عنوان محدّث (إلزامي)', 'جواز سفر سوري إن وُجد', 'شهادات ميلاد الأطفال المسجّلين', 'استمارة العودة الطوعية تُملأ بخط اليد في الإدارة']::text[],
    steps = ARRAY['احجز موعداً عبر randevu.goc.gov.tr', 'احضر إدارة الهجرة الإقليمية → بصمات + استمارة + إذن سفر 15 يوماً', 'توجّه للحدود — معالجة الوثائق + مقابلة بحضور مراقب دولي', 'الخروج النهائي + إتلاف بطاقة الكملك + تسجيل "عودة طوعية"', 'تأكد من عدم وجود ديون أو منع سفر باسمك قبل المغادرة', 'أوقف أوامر الدفع التلقائي (فواتير/اشتراكات).', 'اطلب وثيقة/إشعار إغلاق الحساب.']::text[],
    tips = ARRAY['الإجراء طوعي 100% — يمكن التراجع قبل التوقيع على الاستمارة', 'حضور مراقبين دوليين (UNHCR + الهلال الأحمر) ضمانة قوية', 'بطاقة الكملك تُتلف نهائياً عند العبور — القرار يستوجب التروّي', 'العودة الجديدة لتركيا بعد ذلك تكون بفيزا عادية، ليس بالكملك', 'تأكد من تحديث عنوانك قبل بدء الإجراءات', 'لا تعتمد على “قالوا لي”؛ اعتمد على توجيه رسمي حديث لأن القرارات تتغير.', 'لا تتخذ قرار العودة تحت ضغط — استشر منظمة حقوقية', 'لا تترك معاملات معلقة قد تتحول لدين/ملف تنفيذ.']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'voluntary-return-syria-procedure-2026';

-- النتيجة الحقيقية، ورابط جدول الأكواد بدل تسمية مخترَعة ------------------
UPDATE articles SET details = coalesce(details, '') || '<div style="margin-top:1.25rem;padding:1rem;border-radius:0.75rem;border:1px solid #fecaca;background:#fef2f2;"><p style="margin:0 0 .5rem 0;"><strong>ما الذي تخاطر به فعلاً:</strong> الخروج من تركيا بلا إذن مسبق من مديرية الهجرة قد يُنهي وضعك تحت الحماية المؤقتة — وهذه هي النتيجة التي تعنيك، لا رمز بعينه.</p><p style="margin:0;"><strong>وعن الأكواد:</strong> تتداول صفحات كثيرة أنّ المخالفة «تضع كودَ كذا». راجعنا جدول الأكواد المدقَّق عندنا (125 كوداً) فوجدنا أنّ <strong>V-160</strong> هو تجميد عنوان لا إبطال بطاقة، وأنّ <strong>G-87</strong> كود أمني لتهديد الأمن العام لا نتيجةَ عبورٍ غير نظامي. فلا تصدّق من يخبرك سلفاً بالكود الذي ستناله — وإن رأيت كوداً على ملفك فابحث عن معناه في <a href="/codes" style="color:#b91c1c;font-weight:bold;">صفحة الأكواد الأمنية ←</a></p></div>', last_update = CURRENT_DATE
WHERE slug = 'travel-permit' AND coalesce(details, '') NOT LIKE '%الأكواد المدقَّق%';

-- الصفحات المدموجة والمحذوفة
DELETE FROM articles WHERE slug IN ('travel-permit-2026', 'syria-visit-official', 'syria-travel-permits-kimlik-holders-2026', 'kimlik-leaving-turkey', 'leaving-turkey-final', 'exit-cancel-residence-return-card', 'exit-close-bank-accounts', 'article-عندي-كملك-حماية-مؤقتة-و-نزلت-عودة-طوعبة-إلى-سوريا-و-أرغب-بالعودة-إلى-تركيا');

-- ═══════════════════════════════════════════════════════════════════════════
-- التحقّق — الأول صفّان، والثاني صفر، والثالث صفر (لا كود مخترَع بقي)
SELECT slug, coalesce(array_length(steps,1),0) AS steps,
       coalesce(array_length(tips,1),0) AS tips, last_update
FROM articles WHERE slug IN ('travel-permit', 'syria-turkey-border-crossings-2026', 'voluntary-return-syria-procedure-2026') ORDER BY slug;

SELECT slug FROM articles WHERE slug IN ('travel-permit-2026', 'syria-visit-official', 'syria-travel-permits-kimlik-holders-2026', 'kimlik-leaving-turkey', 'leaving-turkey-final', 'exit-cancel-residence-return-card', 'exit-close-bank-accounts', 'article-عندي-كملك-حماية-مؤقتة-و-نزلت-عودة-طوعبة-إلى-سوريا-و-أرغب-بالعودة-إلى-تركيا');

SELECT slug FROM articles
WHERE status = 'approved'
  AND (details LIKE '%Code V-160%' OR details LIKE '%كود G-87%'
       OR array_to_string(tips, ' ') LIKE '%V-160%');
